-- GenDB engine variant Q12-commuted_comparisons: template q12.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  l_shipmode,
  SUM(
    CASE
      WHEN '1-URGENT' = o_orderpriority OR '2-HIGH' = o_orderpriority
      THEN 1
      ELSE 0
    END
  ) AS high_line_count,
  SUM(
    CASE
      WHEN '1-URGENT' <> o_orderpriority AND '2-HIGH' <> o_orderpriority
      THEN 1
      ELSE 0
    END
  ) AS low_line_count
FROM orders, lineitem
WHERE
  l_orderkey = o_orderkey
  AND l_shipmode IN ($1, $2)
  AND l_receiptdate > l_commitdate
  AND l_commitdate > l_shipdate
  AND $3 <= l_receiptdate
  AND $3 + INTERVAL '1 YEAR' > l_receiptdate
GROUP BY
  l_shipmode
ORDER BY
  l_shipmode
